#include <bits/stdc++.h>
using namespace std;
int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v; scanf("%d%d",&u,&v);
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }
        // Root tree at 1
        vector<int> par(n+1,0), depth(n+1,0), order;
        vector<bool> vis(n+1,false);
        queue<int> q; q.push(1); vis[1]=true;
        while(!q.empty()){int u=q.front();q.pop();order.push_back(u);
            for(auto[v,ei]:adj[u]) if(!vis[v]){vis[v]=true;par[v]=u;depth[v]=depth[u]+1;q.push(v);}}
        int LOG=1; while((1<<LOG)<=n) LOG++;
        vector<vector<int>> up(LOG,vector<int>(n+1,0));
        for(int i=1;i<=n;i++) up[0][i]=par[i];
        for(int k=1;k<LOG;k++) for(int i=1;i<=n;i++) up[k][i]=up[k-1][up[k-1][i]];
        auto lca=[&](int a,int b)->int{
            if(depth[a]<depth[b]) swap(a,b);
            int d=depth[a]-depth[b];
            for(int k=0;k<LOG;k++) if((d>>k)&1) a=up[k][a];
            if(a==b) return a;
            for(int k=LOG-1;k>=0;k--) if(up[k][a]!=up[k][b]){a=up[k][a];b=up[k][b];}
            return up[0][a];
        };
        auto next_toward=[&](int u, int v)->int{
            // next node from u toward v on tree path
            int l=lca(u,v);
            if(u==l){// go down toward v: find ancestor of v at depth[u]+1
                int w=v; for(int k=LOG-1;k>=0;k--) if(depth[up[k][w]]>depth[u]) w=up[k][w];
                return w;
            } else return par[u];
        };
        map<pair<int,int>,int> eid;
        for(int u=1;u<=n;u++) for(auto[v,i]:adj[u]) eid[{u,v}]=i;
        vector<vector<int>> results;
        for(int iter=0;iter<2*n&&iter<5000;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;
            vector<bool> used(n+1,false);
            vector<int> matching;
            // Process in reverse BFS order (leaves first)
            for(int idx=(int)order.size()-1;idx>=0;idx--){
                int u=order[idx];
                if(used[u]||p[u]==u) continue;
                int nxt=next_toward(u,p[u]);
                if(used[nxt]) continue;
                used[u]=used[nxt]=true;
                matching.push_back(eid[{u,nxt}]);
                swap(p[u],p[nxt]);
            }
            if(matching.empty()) break;
            results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto&m:results){printf("%d",(int)m.size());for(int ei:m) printf(" %d",ei+1);printf("\n");}
    }
}
